   "inGuide": true,
   "summary": "資訊安全的核心是 CIA 三要素。機密性：只有被授權者看得到，靠加密與存取控制；完整性：資料正確、完整、沒被未授權竄改，靠雜湊值、數位簽章、變更紀錄；可用性：被授權者需要時就能用，靠備份、備援與負載平衡。生活比喻：機密性是保險箱的鎖、完整性是封條沒被拆、可用性是需要時鑰匙能開門。考試常見：下載頁面提供雜湊值是完整性，DDoS 攻擊是可用性，檔案設密碼是機密性。另有驗證性、可歸責性、不可否認性等延伸性質，但「安全性」不是三要素之一。",
