   "guidePages": "14~15",
   "inGuide": false,
   "summary": "ISO/IEC 27001 在 2022 年改版，考試重點是「哪些是新增」。標準正文與其他 ISO 管理系統的結構調和一致；Annex A 控制措施由 114 項整併為 93 項，分為組織、人員、實體、技術四大類；新增 11 項，例如威脅情資、使用雲端服務的資安、組態管理、資料洩漏預防、網頁過濾。技術漏洞管理、設備汰除或重新使用之保全在舊版就有，不算新增。標題用詞也加入 Cybersecurity 與 Privacy protection。指引未涵蓋，依歷屆考題整理。",
