   "summary": "多因子認證（MFA）是同時使用至少兩種「不同類別」的驗證因子（所知、所有、所具），讓攻擊者就算拿到其中一個，也過不了關。它能降低的是「單一憑證被突破或被冒用」的風險，例如密碼被猜中、暴力破解、鍵盤側錄、只靠生物特徵被竊取或挾持。但第二因子要選得好：IC 識別證加手機隨機驗證碼是好組合；身分證字號、出生年月日這類固定個資容易被查到，且和密碼同屬「知識」類，不能當有效的第二因子。MFA 防的是驗證被突破，並不是用來防「個資拼圖」（零散個資被拼湊起來）。指引也建議除密碼外宜考慮多因素驗證。",
