   "summary": "數位簽章像網路上的親筆簽名：寄件人用「自己的私鑰」對訊息摘要（雜湊值）簽署，收件人用寄件人的「公鑰」驗證。能確認三件事：資料完整性（沒被改）、來源（是誰簽的）、不可否認性（簽了不能賴），但它不負責把訊息內容藏起來。公鑰要向收件人信任的憑證機構（CA）註冊，屬 PKI 的應用，可用 RSA、ElGamal 等演算法實作。數位信封則是用對稱金鑰加密資料（快），再用收件人的公鑰加密該對稱金鑰，兼顧效率與機密性。口訣：加密是「公鑰加、私鑰解」，簽章是「私鑰簽、公鑰驗」。",
