   "summary": "資安事件發生後不能亂槍打鳥，要照固定流程處理，就像消防隊：平時準備、接報判斷、圍堵滅火、善後檢討。NIST SP 800-61 Rev.2 把它分成四階段：準備、偵測與分析、封鎖／根除／復原、事後活動。偵測與分析要先確認事件是否成立，並界定影響範圍、做嚴重度分級；封鎖是先限制擴散；根除是移除根本原因，遇到 Rootkit 這類清不乾淨的，就回存乾淨備份或全新安裝。指引另介紹 ITIL 事故管理九步驟（確認、記錄、分類、優先等級、初診、提升、調查診斷、解決復原、關閉）。考試愛考「某個動作屬於哪個階段」。（註：NIST 已於 2025 年 4 月發布 Rev.3、改用 CSF 2.0 架構，但考題仍考 Rev.2 四階段）",
