   "summary": "備份有幾種方式，差別在於「備份什麼」與「還原要拿幾包」。全部備份（Full）：把所有資料完整複製一次，還原最簡單，但最耗時耗空間。增量備份（Incremental）：只備份上一次「全部備份或增量備份」之後有變動的資料，備份最快、最省空間，但還原時要先還原完整備份，再依序還原每一次增量。差異備份（Differential）：備份「上次完整備份之後」所有變動的資料，還原只需完整備份加最近一次差異備份。選擇式備份（Selective）：只備份系統的一部分。考試最愛問：週一完整、週二至週四增量，週五要還原，要還原週一加週二、三、四全部。",
